326:function button(testid,label,action,extra=''){return `<button ${testid?`data-testid="${testid}"`:''} data-action="${action}" ${extra}>${label}</button>`;}
327:function slots(){const start=Math.ceil((s.now+20*60000)/(15*60000))*15*60000;return Array.from({length:8},(_,i)=>{const t=start+i*15*60000;return {t,value:iso(t).slice(11,16)+'-'+iso(t+15*60000).slice(11,16),date:day(t)};});}
328:function ensureSlot(){const list=slots();if(!list.some(x=>x.t===u.slot))u.slot=list[0].t;return list;}
329:function openTable(table){let x=s.sessions.find(x=>x.table_id===table&&x.state==='open');if(!x){x={id:'S-'+String(s.nextSession++).padStart(4,'0'),table_id:table,state:'open',opened_at:iso(),closed_at:null,cart:[]};s.sessions.push(x);}return x;}
330:function openMenu(){if(u.mode==='dine-in'){const next=openTable(u.table);if(u.session!==next.id){u.selectedMenu=null;u.selectedOptions=[];u.orderMessage='';}u.session=next.id;}else{u.takeawayOpened=true;ensureSlot();}render();}
