 id,b=blocks[i],blocks[i+1].split('\\n## ',1)[0]; ids.append(id)
 us='-'.join(id.split('-')[1:3]); n=int(id.split('-')[-1])
 if n>=101: errors.append(id+' reserved ID')
 for field in fields:
  if len(re.findall(r'"'^- '"'+re.escape(field)+':',b,re.M))"'!=1: errors.append(id+'"' field '+field)
 vals={m.group(1):m.group(2) for m in re.finditer(r'"'^- ([''^:'"\\n]+): ?(.*)"'$'"',b,re.M)}
 if vals.get('AC ต้นฉบับเต็ม')"'!=rows[us].split('"'|')[-2].strip(): errors.append(id+' AC mismatch')
 if vals.get('เจ้าของ')"'!='"'customer': errors.append(id+' owner')
 if vals.get('Status') not in ['NOT_RUN','NOT_TESTABLE']: errors.append(id+' status')
 if vals.get('Actual result')"'!='"'ไม่มีข้อมูล' or vals.get('หลักฐาน')"'!='"'ไม่มีข้อมูล': errors.append(id+' unsupported evidence')
 coverage.setdefault(us,set()).add(vals.get('ประเภท'))
 stats[vals.get('Status')]=stats.get(vals.get('Status'),0)+1
if len(ids)"'!=len(set(ids)): errors.append('"'duplicate IDs')
for i in range(1,10):
 us=f'US-{i:02}'
 if rows[us] not in t: errors.append(us+' original US row missing')
 kinds=coverage.get(us,set())
 if 'สำเร็จ' not in kinds or not ({'ผิดพลาด','ข้อยกเว้น'}&kinds): errors.append(us+' minimum coverage missing')
for target in re.findall(r'\\]\\((["'^)]+)'"\\)',t):
 if not Path(target.split('#')[0]).exists(): errors.append('missing link '+target)
for term in ['/root/','TASK_ID','RUN_ID','work/','cyolo','yolo']:
 if term in t: errors.append('prohibited metadata/path '+term)
print(json.dumps({'scenario_count':len(ids),'status_counts':stats,'source_US_rows_exact':9,'AC_fields_exact':len(ids),'required_fields':len(fields),'coverage':{k:sorted(v) for k,v in coverage.items()},'errors':errors},ensure_ascii=False,indent=2))
PY"

